import logging

import torch
import triton
import triton.language as tl

import flag_gems

_MAX_GRID_X = 65535  # device grid-dimension limit (Ascend coreDim <= 65535)

logger = logging.getLogger(__name__)


@triton.jit
def _safe_softmax_kernel(
    input_ptr, output_ptr, n_rows, n_cols, BLOCK_SIZE: tl.constexpr
):
    row_id = tl.program_id(0)
    # Grid-stride loop: the launch grid is capped (see _MAX_GRID_X).
    row_step = tl.num_programs(0)
    cols = tl.arange(0, BLOCK_SIZE)
    mask = cols < n_cols
    while row_id < n_rows:
        row_offset = row_id * n_cols
        x = tl.load(input_ptr + row_offset + cols, mask=mask, other=-float("inf"))
        x_fp32 = x.to(tl.float32)

        x_max = tl.max(x_fp32, axis=0)
        all_neginf = x_max == -float("inf")

        x_shifted = x_fp32 - x_max
        exp_x = tl.exp(x_shifted)
        sum_exp = tl.sum(exp_x, axis=0)
        softmax = exp_x / sum_exp

        softmax = tl.where(
            all_neginf, tl.zeros([BLOCK_SIZE], dtype=tl.float32), softmax
        )

        tl.store(output_ptr + row_offset + cols, softmax, mask=mask)
        row_id += row_step


@triton.jit
def _safe_softmax_batched_kernel(
    input_ptr,
    output_ptr,
    n_rows,
    n_cols,
    ROWS: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    """Row-batched single-tile softmax.

    One narrow row per program leaves the vector unit mostly idle; batching
    ``ROWS`` rows into one ``[ROWS, BLOCK_SIZE]`` tile restores the block width
    the hardware needs while keeping the row-wise reduction.
    """
    pid = tl.program_id(0)
    step = tl.num_programs(0)
    cols = tl.arange(0, BLOCK_SIZE)[None, :]
    col_mask = cols < n_cols
    row_base = pid * ROWS
    while row_base < n_rows:
        rows = row_base + tl.arange(0, ROWS)[:, None]
        mask = col_mask & (rows < n_rows)
        offsets = rows * n_cols + cols
        x = tl.load(input_ptr + offsets, mask=mask, other=-float("inf"))
        x_fp32 = x.to(tl.float32)
        x_max = tl.max(x_fp32, axis=1)
        all_neginf = x_max == -float("inf")
        exp_x = tl.exp(x_fp32 - x_max[:, None])
        sum_exp = tl.sum(exp_x, axis=1)
        softmax = exp_x / sum_exp[:, None]
        softmax = tl.where(all_neginf[:, None], 0.0, softmax)
        tl.store(output_ptr + offsets, softmax, mask=mask)
        row_base += step * ROWS


@triton.jit
def _safe_softmax_wide_kernel(
    input_ptr, output_ptr, n_rows, n_cols, BLOCK_SIZE: tl.constexpr
):
    """Softmax over rows wider than one tile.

    ``tl.arange`` blocks are bounded, so a row longer than ``BLOCK_SIZE`` is
    handled with an online max/sum pass (rescaling the running sum like
    flash-attention) followed by a normalize pass.  Two reads of the row buy
    correctness for arbitrarily wide reductions.
    """
    row_id = tl.program_id(0)
    row_step = tl.num_programs(0)
    cols = tl.arange(0, BLOCK_SIZE)
    n_tiles = tl.cdiv(n_cols, BLOCK_SIZE)
    neg_inf = -float("inf")
    while row_id < n_rows:
        row_offset = row_id * n_cols
        running_max = neg_inf
        running_sum = 0.0
        for tile in range(n_tiles):
            offs = tile * BLOCK_SIZE + cols
            x = tl.load(
                input_ptr + row_offset + offs, mask=offs < n_cols, other=neg_inf
            )
            x = x.to(tl.float32)
            tile_max = tl.max(x, axis=0)
            new_max = tl.maximum(running_max, tile_max)
            running_sum = running_sum * tl.exp(running_max - new_max) + tl.sum(
                tl.exp(x - new_max), axis=0
            )
            running_max = new_max
        all_neginf = running_max == neg_inf
        for tile in range(n_tiles):
            offs = tile * BLOCK_SIZE + cols
            mask = offs < n_cols
            x = tl.load(input_ptr + row_offset + offs, mask=mask, other=neg_inf)
            y = tl.exp(x.to(tl.float32) - running_max) / running_sum
            y = tl.where(all_neginf, 0.0, y)
            tl.store(output_ptr + row_offset + offs, y, mask=mask)
        row_id += row_step


def _safe_softmax(x: torch.Tensor, dim: int = -1, dtype: torch.dtype = None):
    logger.debug("GEMS _SAFE_SOFTMAX")
    assert (
        x.device.type == flag_gems.device
    ), f"Input tensor must be on {flag_gems.device} device"
    assert x.ndim >= 1, "Input tensor must have at least 1 dimension"

    dim = dim if dim >= 0 else x.ndim + dim
    assert 0 <= dim < x.ndim, "Invalid dim for softmax"

    if dim != x.ndim - 1:
        perm = list(range(x.ndim))
        perm[dim], perm[-1] = perm[-1], perm[dim]
        y = x.permute(perm).contiguous()
        inv_perm = [0] * x.ndim
        for i, p in enumerate(perm):
            inv_perm[p] = i
    else:
        y = x.contiguous()
        inv_perm = None

    n_cols = y.shape[-1]
    n_rows = y.numel() // n_cols

    y_fp32 = y.float()
    out_fp32 = torch.empty_like(y_fp32)

    def _next_pow2(v: int) -> int:
        if v <= 1:
            return 1
        return 1 << (v - 1).bit_length()

    grid = (min(n_rows, _MAX_GRID_X),)
    if n_cols <= 4096:
        # One tile covers the whole row: a single pass is enough.
        block = max(1, _next_pow2(n_cols))
        if block <= 4096:
            rows = max(1, min(64, 8192 // block))
            _safe_softmax_batched_kernel.run(
                y_fp32,
                out_fp32,
                n_rows,
                n_cols,
                ROWS=rows,
                BLOCK_SIZE=block,
                grid=(min(triton.cdiv(n_rows, rows), _MAX_GRID_X),),
                warmup=False,
            )
        else:
            _safe_softmax_kernel.run(
                y_fp32,
                out_fp32,
                n_rows,
                n_cols,
                BLOCK_SIZE=block,
                grid=grid,
                warmup=False,
            )
    else:
        # Rows wider than the largest block use the online two-pass kernel.
        _safe_softmax_wide_kernel.run(
            y_fp32, out_fp32, n_rows, n_cols, BLOCK_SIZE=16384, grid=grid, warmup=False
        )

    out = out_fp32
    if dtype is not None:
        out = out.to(dtype)
    else:
        out = out.to(x.dtype)

    out = out.view(*y.shape)
    if inv_perm is not None:
        out = out.permute(inv_perm)

    return out
